<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { state, scope, ui, replace } from '../state';
import { applyDataset, applyWorkbook, checkpoint, clone, exportApplication, type Checkpoint } from '../services/application-state';
import { decodeFile, downloadFile, encodeFile } from '../services/data-files';
import { recoveryImportPreview, type RecoveryDelta } from '../services/recovery-preview';
import { parseCubWorkbook, validateWorkbookPreview, type WorkbookPreviewData, type WorkbookLike } from '../features/workbook/workbook-parser';
import WorkbookImportPreview from '../features/workbook/WorkbookImportPreview.vue';
import { LEGACY_KEYS } from '../services/legacy-state';
import type { ImportKind } from '../services/import-validation';
const props=defineProps<{mode:string}>();
const kinds:ImportKind[]=['full','requirements','progress','activities','schedule','trees'];
const kind=ref<ImportKind|'workbook'>('full'),format=ref('json'),pending=ref<{kind:ImportKind;data:unknown;delta:RecoveryDelta;name:string;baseline:string}|null>(null),workbook=ref<WorkbookPreviewData|null>(null),workbookName=ref(''),workbookBaseline=ref(''),revision=ref(0),reset=ref(''),confirmation=ref('');
watch(kind,()=>{pending.value=null;workbook.value=null;});
watch(()=>props.mode,()=>{pending.value=null;workbook.value=null;reset.value='';confirmation.value='';revision.value++;});
const checkpoints=computed(()=>{void revision.value;try{const value=JSON.parse(localStorage.getItem(LEGACY_KEYS.checkpoints)??'[]');return Array.isArray(value)?value as Checkpoint[]:[];}catch{return [];}});
function checkpointKind(c:Checkpoint){return /manual/i.test(c.title)?'manual':/reset/i.test(c.title)?'reset':/import/i.test(c.title)?'import':'automatic';}
const checkpointLabels:Record<string,string>={manual:'Manual recovery point',reset:'Before reset',import:'Before import',automatic:'Automatic safety copy'};
function checkpointDate(at:string){const date=new Date(at);return Number.isNaN(date.getTime())?'Date unavailable':date.toLocaleString('en-AU',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}
function checkpointSummary(c:Checkpoint){const data=c.payload,records=(data.scoutRecords??{}) as Record<string,{completed?:boolean}>,studio=(data.studio??{}) as {schedule?:unknown[]};return `${Array.isArray(data.requirements)?data.requirements.length:0} statements · ${Object.values(records).filter(r=>r?.completed).length} completions · ${studio.schedule?.length??0} weeks`;}
function exportData(k:ImportKind){try{downloadFile('oas-'+k+'.'+format.value,encodeFile(k,exportApplication(state.value!,k,scope.value),format.value));}catch(e){ui.error=String(e);}}
function preview(k:ImportKind,data:unknown,name:string){try{pending.value={kind:k,data,delta:recoveryImportPreview(k,exportApplication(state.value!,k,scope.value),data,state.value!.requirements),name,baseline:JSON.stringify(state.value)};workbook.value=null;}catch(e){ui.error=String(e);}}
async function importFile(event:Event){if(kind.value==='workbook'){await importWorkbook(event);return;}const selectedKind=kind.value,input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{preview(selectedKind,decodeFile(selectedKind,await file.text(),file.name),file.name);}catch(e){ui.error=String(e);}input.value='';}
function apply(){if(!pending.value)return;if(pending.value.baseline!==JSON.stringify(state.value)){ui.error='Data changed after preview. Choose the file again.';return;}try{if(replace('Before importing '+pending.value.kind,applyDataset(state.value!,pending.value.kind,pending.value.data))){pending.value=null;revision.value++;}}catch(e){ui.error=String(e);}}
async function importWorkbook(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const XLSX=await import('xlsx');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,cellStyles:true});workbook.value=validateWorkbookPreview(parseCubWorkbook(wb as unknown as WorkbookLike,XLSX,state.value!.requirements));workbookName.value=file.name;workbookBaseline.value=JSON.stringify(state.value);pending.value=null;}catch(e){ui.error=String(e);}input.value='';}
function applyBook(){if(!workbook.value)return;if(workbookBaseline.value!==JSON.stringify(state.value)){ui.error='Data changed after workbook preview. Import again.';return;}if(replace('Before workbook import',applyWorkbook(state.value!,workbook.value))){workbook.value=null;revision.value++;}}
function manualCheckpoint(){try{checkpoint(localStorage,state.value!,'Manual checkpoint');revision.value++;ui.notice='Checkpoint saved locally';}catch(e){ui.error=String(e);}}
async function applyReset(){if(confirmation.value!=='RESET')return;const next=clone(state.value!);try{
 if(reset.value==='achievements')for(const [key,record] of Object.entries(next.progress.scoutRecords))if(!key.endsWith('::__roster__'))next.progress.scoutRecords[key]={...record,completed:false,date:'',sessionEvidence:[],occurrences:0};
 if(reset.value==='scouts'||reset.value==='factory')next.progress.scoutRecords={};
 if(reset.value==='schedule'||reset.value==='factory')next.studio.schedule=[];
 if(reset.value==='requirements'||reset.value==='factory'){const r=await fetch(new URL('data/requirements.json',document.baseURI));if(!r.ok)throw new Error('Default curriculum could not be loaded');next.requirements=(await r.json()).requirements;}
 if(reset.value==='factory'){next.progress.activities=[];next.studio={trees:[],order:{},tags:[],schedule:[],history:[],treeGraphs:{},strategy:'progress',weeks:10,capacity:4};}
 if(replace('Before reset: '+reset.value,next)){reset.value='';confirmation.value='';revision.value++;}
 }catch(e){ui.error=String(e);}}
</script>
<template><section><article v-if="mode==='Monitoring'" class="panel"><h2>Current state</h2><p>{{state!.requirements.length}} requirements · {{Object.keys(state!.progress.scoutRecords).length}} evidence / roster records · {{state!.progress.activities?.length??0}} activities · {{state!.studio.schedule?.length??0}} scheduled weeks.</p><p>Imports and edits create safety checkpoints before changing data. Full JSON or YAML backups preserve nested evidence and editor metadata.</p><button @click="manualCheckpoint">Save checkpoint</button></article>
 <article v-if="mode==='Importer'" class="panel"><h2>Import data</h2><label>Dataset<select v-model="kind" aria-label="Dataset"><option v-for="k in kinds" :key="k" :value="k">{{k}}</option><option value="workbook">Original Scout progress workbook (.xlsx)</option></select></label><label><span>{{kind==='workbook'?'Choose original Scout progress workbook (.xlsx)':'Choose JSON / YAML / OAS CSV'}}</span><input :key="kind" type="file" :accept="kind==='workbook'?'.xlsx':'.json,.yaml,.yml,.csv'" :aria-label="kind==='workbook'?'Choose original Scout progress workbook (.xlsx)':'Choose JSON / YAML / OAS CSV'" @change="importFile"></label><section v-if="workbook" class="preview"><WorkbookImportPreview :filename="workbookName" :preview="workbook" :on-apply="applyBook" :on-cancel="()=>workbook=null" /></section></article>
 <article v-if="mode==='Exporter'" class="panel"><h2>Export data</h2><label>Export format<select v-model="format"><option value="json">JSON</option><option value="yaml">YAML</option><option value="csv">OAS CSV</option></select></label><div class="toolbar"><button v-for="k in kinds" :key="k" @click="exportData(k)">Export {{k}}</button></div></article>
 <article v-if="mode==='Recovery and reset'" class="panel"><h2>Recovery and reset</h2><p>Six full safety checkpoints are retained locally. Download a full backup for longer retention.</p><div class="recovery-heading"><h3>Saved recovery points</h3><button @click="manualCheckpoint">Save recovery point now</button></div><div class="checkpoint-list"><div v-for="(c,i) in checkpoints" :key="i" :class="['checkpoint-card',checkpointKind(c),{newest:i===0}]"><div class="checkpoint-symbol" aria-hidden="true">↶</div><div class="checkpoint-copy"><div class="checkpoint-badges"><span>{{checkpointLabels[checkpointKind(c)]}}</span><span v-if="i===0" class="latest-badge">Most recent</span></div><h4>{{c.title}}</h4><time :datetime="c.at">{{checkpointDate(c.at)}}</time><p>{{checkpointSummary(c)}}</p></div><button class="restore-button" @click="preview('full',c.payload,'Checkpoint: '+c.title)">Review restore</button></div><p v-if="!checkpoints.length" class="checkpoint-empty">No recovery points yet. Save one now, or one will be created before your next edit or import.</p></div><div class="recovery-reset"><h3>Reset local data</h3><label>Reset operation<select v-model="reset"><option value="">Choose operation</option><option value="achievements">Clear achievements only</option><option value="scouts">Clear roster and achievements</option><option value="schedule">Clear schedule</option><option value="requirements">Restore default requirements</option><option value="factory">Factory reset</option></select></label><form v-if="reset" @submit.prevent="applyReset"><p>This changes local {{reset}} data. A full checkpoint is saved first. Export a full backup before proceeding.</p><label>Type RESET to apply<input v-model="confirmation"></label><button :disabled="confirmation!=='RESET'">Apply reset</button><button type="button" @click="reset='';confirmation=''">Cancel</button></form></div></article><section v-if="pending" class="preview"><h3>Review {{pending.kind}} import</h3><p>{{pending.name}}</p><p>{{pending.delta.added}} added · {{pending.delta.modified}} modified · {{pending.delta.removed}} removed</p><p>{{pending.delta.description}}</p><button @click="apply">Apply import</button><button @click="pending=null">Cancel</button></section></section></template>
